const norm=t=>String(t||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[’‘]/g,"'");
export function detectSpatialTerms(text='',limit=4){
 const s=norm(text), found=[];
 for(const e of entries){
   const matches=e.aliases.filter(alias=>new RegExp(`(^|[^a-z])${alias.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}(?:s|es)?(?=$|[^a-z])`,'i').test(s));
   if(matches.length){
     const len=Math.max(...matches.map(x=>x.length));
     found.push({...e,matched:matches.sort((a,b)=>b.length-a.length)[0],confidence:'explicit term',rank:len+(e.id==='vestibule'?2:0)});
   }
 }
 return found.sort((a,b)=>b.rank-a.rank).slice(0,Math.max(1,limit));
}

