export function spatialAxonometric(term){
 const body=axonometricShapes[term.diagram||term.id];
 if(!body)return '';
 return `<svg class="spatial-literacy-svg" viewBox="0 0 300 225" role="img" aria-label="${term.term}: schematic axonometric spatial mechanism"><rect width="300" height="225" rx="12" fill="#fff"/><g fill="#364152" font-family="Inter,Arial,sans-serif" font-size="10" font-weight="600">${body}</g></svg>`;
}
const titleCase=s=>String(s||'').replace(/\b[a-z][a-z-]*/gi,w=>w[0].toUpperCase()+w.slice(1));
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const a=(label,url)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const searchDocs=(term,site)=>`https://www.google.com/search?q=${encodeURIComponent('site:'+site+' '+term)}`; 
export function spatialMiniMarkup(text,type){
 const hits=detectSpatialTerms(text,5);
 if(!hits.length)return `<section class="inspector-section spatial-reading-card"><h4>Spatial Reading</h4><p>No specific architectural mechanism was recognised in this node. Select a phrase or search a term in the studio; unsupported concepts will not be given invented diagrams.</p><button type="button" class="secondary-button spatial-open-modal">Explore Spatial Reading ↗</button></section>`;
 const first=hits[0];
 const summary=`<section class="inspector-section spatial-reading-card"><h4>Spatial Reading</h4><div class="spatial-term-chips">${hits.map(h=>`<span>${esc(titleCase(h.term))}</span>`).join('')}</div><p><strong>${esc(titleCase(first.term))}:</strong> ${esc(first.definition)}</p><button type="button" class="secondary-button spatial-open-modal">Explore Plans, Sections & References ↗</button></section>`;
 const examples=`<section class="inspector-section spatial-feature-card" aria-label="Architectural feature examples"><h4>Spatial Feature Examples</h4><p class="spatial-card-intro">Examples of the architectural element itself — not whole buildings.</p>${first.examples.slice(0,3).map(([name,detail])=>`<article class="spatial-feature-item"><strong>${esc(name)}</strong><p>${esc(detail)}</p></article>`).join('')}${hits.length>1?`<p class="spatial-card-intro">${hits.length-1} more matched spatial concept${hits.length>2?'s':''} available in Spatial Reading Studio.</p>`:''}</section>`;
 return summary+examples;
}
export function spatialReadModalMarkup(text,type='note',additionalCases=[],focusedText=''){
 const query=String(focusedText||'').trim();
 const hits=detectSpatialTerms(query||text,8);
 const lead=`<div class="spatial-context"><span class="spatial-eyebrow">READING THE NODE · ${esc(type)}</span><blockquote class="spatial-selectable-source" title="Highlight a phrase to investigate it">${esc(text)}</blockquote><small>Select a word or phrase above and choose <b>Investigate Selection</b>, or type a different architectural term below.</small></div>
 <div class="spatial-term-search"><label for="spatialLookup">Investigate a Spatial Term or Phrase</label><div class="spatial-search-row"><input id="spatialLookup" type="text" value="${esc(query)}" placeholder="e.g. vestibule, corridor, cross-ventilation" autocomplete="off"><button type="button" id="spatialSearchButton" class="primary-button compact">Investigate →</button><button type="button" id="spatialSelectedButton" class="secondary-button" title="First highlight words in the sentence above">Investigate Selection</button></div><p id="spatialSearchStatus" role="status">${query?'Investigating: '+esc(query):'Recognised architectural terms below are shown separately.'}</p></div>`;
 if(!hits.length)return `<div class="spatial-modal"><h2>Spatial Reading Studio <small class="spatial-version">C2.0</small></h2>${lead}<div class="spatial-unmatched"><h3>No Verified Spatial Diagram for This Phrase</h3><p>${query?'“'+esc(query)+'” is not yet represented by a precise diagram.':'No matching spatial mechanism could be identified automatically.'} The term can still be investigated: define its spatial action, context and required evidence; do not treat an unrelated sketch as a valid architectural explanation.</p><ol><li><b>Identify:</b> What physical element, space, relation or operation does the term describe?</li><li><b>Locate:</b> What is it next to, above, below or between?</li><li><b>Test:</b> Which plan, section, axonometric and site-specific checks would demonstrate it?</li></ol><p>Search for the closest architectural concept or select a keyword from the original node.</p></div>${researchMarkup(query||text)}<div class="modal-actions"><button class="secondary-button" data-close-modal>Back to Map</button></div></div>`;
 const tabs=`<nav class="spatial-term-tabs" aria-label="Detected architectural terms">${hits.map((h,i)=>`<button type="button" class="spatial-term-tab ${i===0?'active':''}" data-spatial-tab="${esc(h.id)}">${esc(titleCase(h.term))}</button>`).join('')}</nav>`;
 const panels=hits.map((h,i)=>{
  const tagMap={vestibule:['vestibule'],threshold:['threshold'],corridor:['circulation','route'],courtyard:['courtyard'],atrium:['atrium'],ramp:['ramp'],partition:['partition','screen'],canopy:['canopy'],seating:['seating'],facade:['facade'],daylight:['daylight'],stair:['stair'],flexibility:['flexibility','reconfiguration']};
  const mapped=additionalCases.filter(c=>(c.tags||[]).some(tag=>(tagMap[h.id]||[h.id]).includes(norm(tag)))).map(c=>({id:c.id,title:c.name,architect:c.designer,year:c.year,feature:c.feature,url:c.sourceUrl})).filter(c=>c.url);
  const cas=[...projectCases.filter(c=>c.tags.includes(h.id)||h.projectIds.includes(c.id)),...mapped].filter((v,i,a)=>a.findIndex(x=>x.id===v.id)===i).slice(0,5);
  return `<section class="spatial-term-panel ${i===0?'active':''}" data-spatial-panel="${h.id}"><div class="spatial-term-intro"><span class="spatial-eyebrow">MATCHED PHRASE: ${esc(h.matched)} · EXPLICIT TERM</span><h3>${esc(titleCase(h.term))}</h3><p>${esc(h.definition)}</p><p><b>What It Does Spatially:</b> ${esc(h.operation)}</p></div><div class="spatial-study-views"><figure>${spatialDiagram(h,'plan')}<figcaption>Plan · diagrammatic spatial relationships, not a scaled drawing</figcaption></figure><figure>${spatialDiagram(h,'section')}<figcaption>Section / Elevation · Operational Arrangement</figcaption></figure>${spatialAxonometric(h)?`<figure class="spatial-axo-figure">${spatialAxonometric(h)}<figcaption>Axonometric · Conceptual Mechanism, Not a Construction Model</figcaption></figure>`:''}</div><div class="spatial-read-columns"><section><h4>Test in the Design</h4><ol>${h.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section><h4>Spatial Feature Examples</h4><p class="spatial-subhead">Architectural types and spatial configurations — not building recommendations.</p>${h.examples.map(([title,detail])=>`<article class="spatial-example"><strong>${esc(title)}</strong><p>${esc(detail)}</p></article>`).join('')}</section></div><div class="spatial-read-columns"><section><h4>Built Projects Using This Feature</h4><p class="spatial-subhead">Named projects are shown separately from examples of the architectural element.</p>${cas.length?cas.map(c=>`<article class="spatial-example"><strong>${esc(c.title)}</strong><small>${esc(c.architect)} · ${esc(c.year)}</small><p>${esc(c.feature)}</p>${a('Open documented project',c.url)}</article>`).join(''):'<p class="spatial-subhead">No documented project example is currently verified for this exact feature. TRACEWORK will not substitute an unrelated pavilion.</p>'}<p>${a('Search documented projects about this feature',searchDocs(h.term,'archdaily.com'))}</p></section><section><h4>Readings, Guidance & Drawings</h4>${h.reading.length?h.reading.map(([label,url])=>`<p>${a(label,url)}</p>`).join(''):'<p class="spatial-subhead">No verified reading attached to this term yet; the diagram and variants are learning prompts only.</p>'}<p>${a('Search academic literature on this term',`https://scholar.google.com/scholar?q=${encodeURIComponent(h.term)}`)}</p><p class="spatial-subhead">Code and accessibility checks are location-specific. Always verify governing standards for the actual project.</p></section></div></section>`;
 }).join('');
 return `<div class="spatial-modal"><h2>Spatial Reading Studio <small class="spatial-version">C2.0</small></h2>${lead}${tabs}${panels}${researchMarkup(query||text,{compact:true})}<div class="modal-actions"><button class="secondary-button" data-close-modal>Back to Map</button></div></div>`;
}
export function bindSpatialModal(modal,{onSearch}={}){
 const root=modal.querySelector('.spatial-modal');
 if(!root)return;
 const input=root.querySelector('#spatialLookup');
 const status=root.querySelector('#spatialSearchStatus');
 const submit=query=>{
   const requested=String(query||'').trim();
   if(!requested){if(status)status.textContent='Select or enter an architectural term first.';input?.focus();return;}
   if(typeof onSearch==='function')onSearch(requested);
 };
 root.querySelector('#spatialSearchButton')?.addEventListener('click',()=>submit(input?.value));
 input?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();submit(input.value);}});
 let selection='';
 const quote=root.querySelector('.spatial-selectable-source');
 quote?.addEventListener('mouseup',()=>{
   const picked=window.getSelection();
   if(picked && quote.contains(picked.anchorNode) && quote.contains(picked.focusNode))selection=picked.toString().trim();
   if(selection && status)status.textContent=`Selected: “${selection.slice(0,110)}” · Click Investigate Selection`;
 });
 root.querySelector('#spatialSelectedButton')?.addEventListener('click',()=>{
   let selected=selection;
   const picked=window.getSelection();
   if(picked && quote?.contains(picked.anchorNode) && quote.contains(picked.focusNode))selected=picked.toString().trim()||selected;
   if(!selected){if(status)status.textContent='First highlight the word or phrase in the node sentence.';return;}
   submit(selected);
 });
 root.querySelectorAll('[data-spatial-tab]').forEach(btn=>btn.onclick=()=>{
  const id=btn.dataset.spatialTab;
  root.querySelectorAll('[data-spatial-tab]').forEach(el=>{const active=el===btn;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));});
  root.querySelectorAll('[data-spatial-panel]').forEach(el=>el.classList.toggle('active',el.dataset.spatialPanel===id));
 });
}
